170:   if (!raw || typeof raw !== 'object') return livery;
171:   for (const part of LIVERY_PARTS) {
172:     const hex = normalizeHex(raw[part.id]);
173:     if (hex) livery[part.id] = hex;
174:   }
175:   for (const slot of STICKER_SLOTS) {
176:     const choice = raw.stickers?.[slot.id];
177:     livery.stickers[slot.id] = STICKER_CHOICES.some((item) => item.id === choice) ? choice : null;
178:   }
179:   return livery;
180: }
