481: function updateDrawStats(preview) {
482:   if (!preview) {
483:     dom.statLength.textContent = '—';
484:     dom.statTurns.textContent = '—';
485:     dom.statStraight.textContent = '—';
486:     dom.readoutLength.textContent = '0 m';
487:     dom.readoutTurns.textContent = '0 turns';
488:     dom.drawStatus.textContent = 'DRAW A CLOSED LOOP';
489:     dom.btnBuild.disabled = true;
490:     dom.validationInline.classList.remove('show');
491:     setValidation('error', 'CIRCUIT INCOMPLETE', 'Draw one continuous loop to unlock the build.');
492:     return;
493:   }
494: 
495:   dom.statLength.textContent = preview.length.toLocaleString();
496:   dom.statTurns.textContent = preview.turns;
497:   dom.statStraight.textContent = preview.longestStraight.toLocaleString();
498:   dom.readoutLength.textContent = `${preview.length.toLocaleString()} m`;
499:   dom.readoutTurns.textContent = `${preview.turns} turns`;
500: 
501:   if (preview.selfIntersects) {
502:     dom.drawStatus.textContent = 'SELF-INTERSECTION DETECTED';
503:     dom.btnBuild.disabled = true;
504:     setValidation('error', 'TRACK CROSSES ITSELF', 'Erase and redraw one clean loop. Bridges arrive in APEX INK 2.');
505:     dom.validationInline.textContent = 'FIX THE CROSSING';
506:     dom.validationInline.classList.add('show');
507:   } else if (preview.tooFew) {
508:     dom.drawStatus.textContent = 'KEEP DRAWING';
509:     dom.btnBuild.disabled = true;
510:     setValidation('error', 'THAT IS A SCRIBBLE', 'Hold and drag to sketch a full circuit — bigger than a dot.');
511:     dom.validationInline.textContent = 'LOOP TOO SHORT';
512:     dom.validationInline.classList.add('show');
513:   } else if (preview.tooSmall) {
514:     dom.drawStatus.textContent = 'DRAW BIGGER';
515:     dom.btnBuild.disabled = true;
516:     setValidation('error', 'A LITTLE TOO POCKET-SIZED', 'Give us a larger loop so the car has somewhere to breathe.');
517:     dom.validationInline.textContent = 'TRY A BIGGER LOOP';
518:     dom.validationInline.classList.add('show');
519:   } else if (preview.valid && preview.minRadius > 0 && preview.minRadius < 26) {
520:     dom.drawStatus.textContent = 'CIRCUIT READY · TIGHT';
521:     dom.btnBuild.disabled = false;
522:     setValidation('warning', 'TIGHT & TECHNICAL', 'Approved — but those hairpins will bite. The AI will struggle too.');
523:     dom.validationInline.classList.remove('show');
524:   } else if (preview.valid) {
525:     dom.drawStatus.textContent = 'CIRCUIT APPROVED';
526:     dom.btnBuild.disabled = false;
527:     setValidation('valid', 'CIRCUIT APPROVED', `${preview.turns} corners · start/finish locked. Ready to pour asphalt.`);
528:     dom.validationInline.textContent = 'READY TO BUILD';
529:     dom.validationInline.classList.add('show');
530:   } else {
531:     dom.drawStatus.textContent = 'DRAW A CLOSED LOOP';
532:     dom.btnBuild.disabled = true;
533:     setValidation('error', 'CIRCUIT INCOMPLETE', 'Keep the line continuous and close the loop.');
534:   }
535: }
