2424:       if (d < -4 || d > 15) continue;
2425:       if (Math.abs(b.lateral - lat) < AI_MIN_SIDE_GAP) { clear = false; break; }
2426:     }
2427:     const room = side < 0 ? blocker.lateral + limit : limit - blocker.lateral;
2428:     options.push({
2429:       side, lat, clear, room,
2430:       score: (clear ? 20 : 0) + room + (side === inside ? 1.2 : 0)
2431:     });
2432:   }
2433:   options.sort((x, y) => y.score - x.score);
