2514: function aiPitFollowSpeed(a, target) {
2515:   const traffic = aiPitAhead(a);
2516:   if (!traffic) return target;
2517:   const gap = traffic.gap;
2518:   if (gap >= AI_PIT_FOLLOW_GAP) return target;
2519:   // Close the gap smoothly, then hold station behind the car in front. The
2520:   // 0.8 m/s margin avoids an accordion at the limiter.
2521:   const follow = Math.max(0, traffic.car.pit.speed + (gap - AI_PIT_MIN_GAP) * 1.6 - 0.8);
