const runtime = process.env.HOME + '/.local/share/omgithub-playwright';
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: false, executablePath: '/opt/google/chrome/chrome' });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.on('pageerror', e => console.log('PAGEERROR', e.message));
await page.goto('http://localhost:3000/?demo=race&track=0', { waitUntil: 'domcontentloaded' });
await page.waitForFunction(() => window.__apex?.race, null, { timeout: 30000 });
await page.evaluate(() => {
  const r = window.__apex.race;
  const before = {
    player: { x:r.player.pos.x, z:r.player.pos.z, yaw:r.player.yaw },
    ai: r.ai.map(a => ({ name:a.name, x:a.model.root.position.x, z:a.model.root.position.z, yaw:a.model.root.rotation.y, dist:a.dist }))
  };
  window.__gridProbe = { before, samples: [], maxJump: 0, maxJumpInfo: null, firstRacing: null };
  let last = null;
  let lastState = r.state;
  function run() {
    if (r.state === 'racing') {
      const now = {
        t: r.time,
        player: { x:r.player.pos.x, z:r.player.pos.z, yaw:r.player.yaw, pd:r.player.progressDist, v:r.player.vLong },
        ai: r.ai.map(a => ({ name:a.name, x:a.model.root.position.x, z:a.model.root.position.z, yaw:a.model.root.rotation.y, dist:a.dist, sp:a.speed }))
      };
      if (!window.__gridProbe.firstRacing) window.__gridProbe.firstRacing = now;
      if (last) {
        const jumps = [['player', now.player, last.player]];
        for (let i=0;i<now.ai.length;i++) jumps.push([now.ai[i].name, now.ai[i], last.ai[i]]);
        for (const [name, a, b] of jumps) {
          const d = Math.hypot(a.x-b.x, a.z-b.z);
          if (d > window.__gridProbe.maxJump) {
            window.__gridProbe.maxJump = d;
            window.__gridProbe.maxJumpInfo = { name, d, from:b, to:a, t: now.t };
          }
        }
      }
      window.__gridProbe.samples.push(now);
      if (window.__gridProbe.samples.length > 180) window.__gridProbe.samples.shift();
      last = now;
    } else {
      last = null;
    }
    lastState = r.state;
    requestAnimationFrame(run);
  }
  requestAnimationFrame(run);
});
await page.waitForTimeout(9000);
const data = await page.evaluate(() => {
  const p = window.__gridProbe;
  return { before: p.before, firstRacing: p.firstRacing, maxJump: p.maxJump, maxJumpInfo: p.maxJumpInfo, n: p.samples.length, last: p.samples[p.samples.length-1] };
});
console.log(JSON.stringify(data, null, 1));
await page.screenshot({ path: '/tmp/opencode/start-real.jpg', type: 'jpeg', quality: 72 });
await browser.close();

