const gp = gridPose(i);
a.dist = gp.dist; ... a.lastYaw=gp.yaw; ...
a.gridDist = gp.dist;
a.gridLateral = gp.lateral;
a.gridPose = { x: gp.x, z: gp.z, yaw: gp.yaw, dist: gp.dist, lateral: gp.lateral, index: gp.index };
```
