    a.lastZ = g.z;
    a.lastYaw = g.yaw;
    a.passLat = g.lateral;
    a.passSide = 0;
    a.passUntil = 0;
    setCarPose(a.model, g.x, g.z, g.yaw);
    a.model.body.rotation.set(0, 0, 0);
  }
}

function startRaceNow() {
  const r = race;
  anchorCarsToGrid();
  r.state = 'racing';
  r.time = 0;
