const info = await page.evaluate(() => {
  const r = window.__apex.race;
  window.__apex.startRaceNow();
  r.state = 'paused';
  const box = r.world.playerPitBox;
  r.camera.position.set(box.x - Math.cos(box.yaw) * 9 + Math.sin(box.yaw) * 2, 10.5, box.z + Math.sin(box.yaw) * 9 + Math.cos(box.yaw) * 2);
  r.camera.lookAt(box.x, 0.5, box.z);
  return { crew: box.crew.length, phase: r.pit.phase, states: box.crew.map((c) => ({ x: c.x, z: c.z, y: c.group.position.y })) };
});
